{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_item_name = doc.get('custom_print_item_name') if doc.get('custom_print_item_name') is not none else 1 %}{% set show_sku = doc.get('custom_print_sku') if doc.get('custom_print_sku') is not none else 1 %}{% set show_color_code = doc.get('custom_print_color_code') if doc.get('custom_print_color_code') is not none else 1 %}{% set show_description = doc.get('custom_print_description') if doc.get('custom_print_description') is not none else 1 %}{% set show_images = 0 %}
<div class="company-header"><h2>Confirmação de Encomenda / 订单确认单</h2></div>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">历史单据未保存打印快照，所示补充主资料为当前资料。</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>交期: {{ doc.get('delivery_date') or '—' }}</td></tr></table>
<table class="items"><colgroup>{% if show_item_name %}<col data-col="name" class="col-item">{% endif %}{% if show_sku %}<col data-col="sku" class="col-sku">{% endif %}{% if show_color_code %}<col data-col="cor" class="col-color-code">{% endif %}<col data-col="barcode" class="col-barcode">{% if show_description %}<col data-col="description" class="col-description">{% endif %}<col data-col="qty" class="col-qty"><col data-col="uom" class="col-uom"><col data-col="rate" class="col-rate"><col data-col="amount" class="col-amount"></colgroup><caption class="items-title">{{ doc.name | e }} · Encomenda / 订购</caption><thead><tr>{% if show_images %}<th class="col-photo">FOTO&nbsp;</th>{% endif %}{% if show_item_name %}<th class="col-item">Artigo / 商品</th>{% endif %}{% if show_sku %}<th class="col-sku">SKU / 货号</th>{% endif %}{% if show_color_code %}<th class="col-color-code">COR</th>{% endif %}<th class="col-barcode">EAN / 条码</th>{% if show_description %}<th class="col-description">Descrição / 描述</th>{% endif %}<th class="col-qty">Quantidade / 数量</th><th class="col-uom">Un.</th><th class="col-rate">Preço / 单价</th><th class="col-amount">Valor / 金额</th></tr></thead><tbody>{% for item in p["items"] %}<tr>{% if show_images %}<td class="col-photo">{% if item.template_code %}{% set img = get_color_card_thumbnail(item.template_code) %}{% if img %}<img class="photo" src="{{ img | e }}">{% endif %}{% endif %}</td>{% endif %}{% if show_item_name %}<td class="col-item">{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{{ (item.order_code or item.item_code) | e }}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ item.color_code | e }}</td>{% endif %}<td class="col-barcode">{{ item.barcode | e }}</td>{% if show_description %}<td class="col-description">{{ item.description | e }}</td>{% endif %}<td class="col-qty num">{{ format_print_qty(item.qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td class="col-rate num">{{ format_print_money(item.rate) }}</td><td class="col-amount num">{{ format_print_money(item.amount) }}</td></tr>{% endfor %}</tbody></table>
<div class="qty-total">Total Qty / 总数量: {{ format_print_qty(p.get("total_qty") or 0) }}</div>
<div class="total">Total / 含税合计: {{ format_print_money(doc.grand_total, currency=doc.currency) }} {{ doc.currency }}</div>
<div class="block">Plano de pagamento / 付款安排: {{ p.get("payment_method") or "未维护" | e }} · Depósito / 定金: {{ format_print_money(p.get("deposit"), currency=doc.currency) }} · Vencimento do saldo / 尾款到期: {{ p.get("balance_due_date") or "—" | e }}<br>Plano de faturação / 开票安排: {{ p.get("invoice_plan") or "未维护" | e }}</div>
<div class="footer">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div>
